import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom CUDA kernel for element-wise addition ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Custom CUDA kernel for GroupNorm forward pass ----------
groupnorm_kernel_source = """
#include <torch/extension.h>
#include <cmath>

__global__ void groupnorm_kernel(const float* x, const float* mean, const float* var, float* out, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float val = x[idx];
        out[idx] = (val - mean[idx]) / sqrtf(var[idx] + 1e-5f);
    }
}

torch::Tensor groupnorm_cuda(torch::Tensor x, torch::Tensor mean, torch::Tensor var) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    groupnorm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), mean.data_ptr<float()>, var.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

groupnorm_cpp_source = "torch::Tensor groupnorm_cuda(torch::Tensor x, torch::Tensor mean, torch::Tensor var);"
groupnorm_cuda_source = groupnorm_kernel_source
groupnorm = load_inline(
    name="groupnorm_cuda",
    cpp_sources=groupnorm_cpp_source,
    cuda_sources=groupnorm_cuda_source,
    functions=["groupnorm_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Optimized Model ----------
class ModelNew(nn.Module):
    def __init__(self, num_features: int, num_groups: int):
        super().__init__()
        self.elementwise_add = elementwise_add
        # Store the custom GroupNorm function for forward pass.
        self.groupnorm_cuda = groupnorm

    def _compute_stats(self, x: torch.Tensor) -> tuple:
        """
        Compute per-pixel mean and variance across the feature dimension (axis=1).
        Returns flattened 1‑D tensors of type float32 matching total_elements.
        """
        B = x.size(0)
        C = x.size(1)   # num_features
        H = x.size(2)
        W = x.size(3)

        # mean and var along channel axis for each spatial location (b, h, w)
        mean_per_pixel = x.mean(dim=1, keepdim=True).flatten().view(-1).astype(torch.float32)
        var_per_pixel  = torch.var(x, dim=1, keepdim=True, unbiased=False).flatten().view(-1).astype(torch.float32)

        return mean_per_pixel, var_per_pixel

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply Group Normalization to the input tensor using the custom CUDA kernel.

        Parameters:
            x: Input tensor of shape (batch_size, num_features, dim1, dim2)

        Returns:
            Tensor after per-pixel normalization across the feature dimension.
        """
        mean_flat, var_flat = self._compute_stats(x)
        # Build flat tensors for the custom kernel
        mean_tensor = torch.from_numpy(mean_flat.numpy()).cuda() if x.is_cuda else mean_flat
        var_tensor  = torch.from_numpy(var_flat.numpy()).cuda() if x.is_cuda else var_flat

        out = self.groupnorm_cuda(x, mean_tensor, var_tensor)
        return out
